package hiro.swiftkey; public class JapaneseGlideDecoder {public static final String ASSET="test";public static volatile boolean ready=true,loadFail,blockLoad,blockDecode;public static volatile int calls;public static final java.util.List<Float> starts=java.util.Collections.synchronizedList(new java.util.ArrayList<Float>());public static boolean empty,invalid;public static boolean isReady(){return ready;}public static void load(java.io.InputStream in)throws Exception{while(blockLoad)Thread.sleep(1);if(loadFail)throw new java.io.IOException();ready=true;}public static Result[] decodeCandidates(float[] trace,float[] centers,int[] codes){while(blockDecode)try{Thread.sleep(1);}catch(InterruptedException e){throw new RuntimeException(e);}starts.add(trace[0]);int i=calls++;return empty?new Result[0]:new Result[]{new Result(invalid?"123":i%2==0?"ka":"ki")};}public static class Result{public String romaji,hiragana;public float score,margin;public int scanned;public Result(String s){romaji=hiragana=s;}}}
